// Turns new Instagram messages into conversation turns, for every connected Page. Seen message
// ids live in the workflow's static data; the first poll of a Page only records what is
// already there, so old messages are not answered when a business connects.
const pages = $('Pages with Instagram').all().map(item => item.json);
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
store.pages = store.pages || {};
const cutoff = Date.now() - 15 * 60 * 1000;
const out = [];
$input.all().forEach((item, index) => {
  const page = pages[index];
  const response = item.json;
  if (!page) return;
  if (response.statusCode !== 200) {
    // Usually a token Meta revoked: the owner has to connect again.
    console.log('Instagram poll failed for business', page.businessId, response.statusCode,
      JSON.stringify(response.body?.error ?? {}));
    return;
  }
  const own = page.instagramAccountId;   // our own replies are skipped
  const firstRun = !store.pages[page.pageId];
  store.pages[page.pageId] = Date.now();
  // Several messages from one person in this poll ("hi", "massage", "tomorrow 5pm") become one
  // turn, so they are understood together and answered once instead of racing each other.
  const bySender = new Map();
  for (const conversation of response.body?.data || []) {
    const messages = [...(conversation.messages?.data || [])].reverse();   // oldest first
    for (const m of messages) {
      if (store.seen[m.id]) continue;
      store.seen[m.id] = Date.now();
      if (firstRun) continue;
      if (!m.message || !m.from?.id || m.from.id === own) continue;
      if (new Date(m.created_time).getTime() < cutoff) continue;
      const earlier = bySender.get(m.from.id);
      if (earlier) {
        // The same words twice in a row are one message.
        if (earlier.lastText !== m.message) earlier.text += '\n' + m.message;
        earlier.lastText = m.message;
        earlier.mid = m.id;
        earlier.sentAt = m.created_time;
      } else {
        bySender.set(m.from.id, { businessId: page.businessId, provider: 'INSTAGRAM', externalUserId: m.from.id,
          recipientId: m.from.id, displayName: m.from.username || null, text: m.message, lastText: m.message,
          mid: m.id, sentAt: m.created_time });
      }
    }
  }
  for (const { lastText, ...json } of bySender.values()) out.push({ json });
});
const ids = Object.keys(store.seen);
if (ids.length > 2000) ids.sort((a, b) => store.seen[a] - store.seen[b]).slice(0, ids.length - 1000).forEach(id => delete store.seen[id]);
return out;
